    const { width, height } = this.canvas;
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = 'rgba(8, 13, 20, .86)';
    ctx.fillRect(0, 0, width, height);
    ctx.strokeStyle = 'rgba(255,255,255,.22)';
    ctx.strokeRect(.5, .5, width - 1, height - 1);
    const dx = Math.max(.001, this.bounds.maxX - this.bounds.minX);
    const dz = Math.max(.001, this.bounds.maxZ - this.bounds.minZ);
    for (const point of this.points) {
      const x = ((point.x - this.bounds.minX) / dx) * width;
      const y = height - ((point.z - this.bounds.minZ) / dz) * height;
      ctx.beginPath();
      ctx.fillStyle = point.color ?? '#7cf7d4';
      ctx.arc(x, y, point.radius ?? 4, 0, Math.PI * 2);
      ctx.fill();
      if (point.label) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px system-ui, sans-serif';
        ctx.fillText(point.label, x + 6, y - 5);
      }
    }
  }
