import type * as THREE from 'three';
import { PresentationMinimap } from './PresentationMinimap';

export interface DiagnosticsSnapshot {
  fps: number;
  frameMs: number;
  rendererCalls: number;
  triangles: number;
  camera: { x: number; y: number; z: number };
}

export interface DeveloperDiagnosticsOptions {
  root: HTMLElement;
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.Camera;
  now?: () => number;
}

export class DeveloperDiagnostics {
  readonly minimap = new PresentationMinimap();
  readonly overlay: HTMLDivElement;
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene: THREE.Scene;
  private readonly camera: THREE.Camera;
  private readonly now: () => number;
  private frameCount = 0;
  private windowStart = 0;
  private fps = 0;
  private lastFrame = 0;
  private visible = true;
  private wireframe = false;

  constructor(options: DeveloperDiagnosticsOptions) {
    this.renderer = options.renderer;
    this.scene = options.scene;
    this.camera = options.camera;
    this.now = options.now ?? (() => performance.now());
    this.windowStart = this.now();
    this.lastFrame = this.windowStart;

    this.overlay = document.createElement('div');
    this.overlay.className = 'dev-diagnostics';
    this.overlay.setAttribute('aria-live', 'off');
    options.root.append(this.overlay, this.minimap.element);
    window.addEventListener('keydown', this.onKeyDown);
    this.renderOverlay(this.snapshot(0));
  }

  frame(): void {
    const now = this.now();
    const frameMs = Math.max(0, now - this.lastFrame);
    this.lastFrame = now;
    this.frameCount += 1;
    const elapsed = now - this.windowStart;
    if (elapsed >= 500) {
      this.fps = this.frameCount * 1000 / elapsed;
      this.frameCount = 0;
      this.windowStart = now;
    }
    if (this.visible) this.renderOverlay(this.snapshot(frameMs));
  }

  dispose(): void {
    window.removeEventListener('keydown', this.onKeyDown);
    this.overlay.remove();
    this.minimap.element.remove();
  }

  private snapshot(frameMs: number): DiagnosticsSnapshot {
    const position = this.camera.position;
    return {
      fps: this.fps,
      frameMs,
      rendererCalls: this.renderer.info.render.calls,
      triangles: this.renderer.info.render.triangles,
      camera: { x: position.x, y: position.y, z: position.z },
    };
  }

  private renderOverlay(snapshot: DiagnosticsSnapshot): void {
    this.overlay.textContent = [
      `FPS ${snapshot.fps.toFixed(0)} · ${snapshot.frameMs.toFixed(1)} ms`,
      `Draw ${snapshot.rendererCalls} · Tri ${snapshot.triangles}`,
      `Cam ${snapshot.camera.x.toFixed(1)}, ${snapshot.camera.y.toFixed(1)}, ${snapshot.camera.z.toFixed(1)}`,
      `F1 overlay · F2 wireframe · F3 minimap`,
    ].join('\n');
  }

  private readonly onKeyDown = (event: KeyboardEvent): void => {
    if (event.code === 'F1') {
      event.preventDefault();
      this.visible = !this.visible;
      this.overlay.hidden = !this.visible;
    } else if (event.code === 'F2') {
      event.preventDefault();
      this.wireframe = !this.wireframe;
      this.scene.traverse(object => {
        if (!('material' in object)) return;
        const material = (object as THREE.Mesh).material;
        const materials = Array.isArray(material) ? material : [material];
        for (const item of materials) if (item && 'wireframe' in item) (item as THREE.MeshBasicMaterial).wireframe = this.wireframe;
      });
    } else if (event.code === 'F3') {
      event.preventDefault();
      this.minimap.setVisible(!this.minimap.visible);
    }
  };
}
