describe('InputManager', () => {
  it('tracks keyboard actions across frames', () => {
    const input = new InputManager({ target: window, pointerTarget: document });
    window.dispatchEvent(new KeyboardEvent('keydown', { code: 'KeyW' }));
    expect(input.isDown('camera-forward')).toBe(true);
    expect(input.wasPressed('camera-forward')).toBe(true);
    input.endFrame();
    expect(input.wasPressed('camera-forward')).toBe(false);
    window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyW' }));
    expect(input.wasReleased('camera-forward')).toBe(true);
    input.dispose();
  });

  it('tracks primary pointer and wheel input', () => {
    const input = new InputManager({ target: window, pointerTarget: document });
    document.dispatchEvent(new PointerEvent('pointerdown', { button: 0, clientX: 12, clientY: 34 }));
    expect(input.pointer.primaryDown).toBe(true);
    expect(input.isDown('primary')).toBe(true);
    document.dispatchEvent(new WheelEvent('wheel', { deltaY: 120, cancelable: true }));
    expect(input.pointer.wheel).toBe(120);
    input.endFrame();
    expect(input.pointer.wheel).toBe(0);
    input.dispose();
  });
});
